try {
// Process Email Input: robustly locate form + PRD binary even after Wait
const all = $input.all();
let formItem=null; let prdItem=null;
for(const entry of all){
  if(!formItem && entry.json && (entry.json.Name || entry.json.Email)) formItem=entry;
  if(!prdItem && entry.binary && (entry.binary.data || entry.binary.prd)) prdItem=entry;
}
// Fallback: fetch original PRD item from earlier execution if not in merged inputs
if(!prdItem){
  try {
    const legacy = $items('Convert to Binary',0,0);
    if(legacy && legacy.binary && (legacy.binary.data || legacy.binary.prd)) prdItem = legacy;
  } catch(e) { /* ignore */ }
}
if(!formItem) return []; // No form yet (node may have been executed on the PRD path pre-resume)
if(!prdItem) throw new Error('PRD binary not found. Please regenerate the PRD.');
const name=(formItem.json.Name||'').trim();
const email=(formItem.json.Email||'').trim();
const re=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if(name.length<1) throw new Error('Name must be at least 1 characters');
if(!re.test(email)) throw new Error('Invalid email address');
const binObj = prdItem.binary.data || prdItem.binary.prd;
// Normalize binary: ensure we have { data: base64, mimeType, fileName }
let base64Data, mimeType, fileName;
if(typeof binObj === 'string'){ base64Data = binObj; mimeType='text/markdown'; fileName = (prdItem.json && prdItem.json.fileName) || 'prd_document.md'; }
else { base64Data = binObj.data; mimeType = binObj.mimeType || 'text/markdown'; fileName = (prdItem.json && prdItem.json.fileName) || binObj.fileName || 'prd_document.md'; }
const validationSummary = (prdItem.json && prdItem.json.validationSummary) || 'PRD Generated';
return [{
  json: { fileName, validationSummary, recipientName: name, recipientEmail: email },
  binary: { data: { data: base64Data, mimeType, fileName } }
}];
} catch (err) { console.error('❌ [Process Email Input]:', err.message); throw new Error('[Process Email Input] ' + err.message); }

try {
const i = $input.first().json;
const md = i.markdown || '';
const fn = i.documentFileName || ('prd_' + new Date().toISOString().slice(0, 10) + '.md');
const clean = md.replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/<\/?think>/gi, '');
const b64 = Buffer.from(clean, 'utf8').toString('base64');
const url = $execution.resumeFormUrl;
console.log('📧 Preparing email delivery: '+fn+' size(b64)='+b64.length);
return [{
  json: { fileName: fn, validationSummary: i.summary || 'PRD Generated', message: '✅ PRD ready! Fill form to receive via email: ' + url, webhookUrl: url },
  binary: { data: { data: b64, mimeType: 'text/markdown', fileName: fn } }
}];
} catch (err) { console.error('❌ [Convert to Binary]:', err.message); throw new Error('[Convert to Binary] ' + err.message); }

try {
const i=$input.first().json;
const md=i.markdown||'';

// Extract epic title from Project Name field or fall back to featureName
let epicTitle=i.featureName||'PRD Epic';
const projMatch=md.match(/\*\*Project Name\*\*[:\s]+([^\n\r]+)/i);
if(projMatch) epicTitle=projMatch[1].trim();

// Extract epic description from Product Overview section (first 500 chars)
let epicDescription='';
const overviewMatch=md.match(/#\s*Product Overview([\s\S]*?)(?=\n#|$)/i);
if(overviewMatch) epicDescription=overviewMatch[1].replace(/\*\*[^*]+\*\*:/g,'').trim().substring(0,500);

// Extract functional requirements as tasks (FR1, FR2, etc.) - up to 5
const tasks=[];
const frPat=/\*\*(FR\d+)\*\*[:\s]+([^\n\r]+)/g;
let fm;
while((fm=frPat.exec(md))!==null&&tasks.length<5){
  tasks.push({id:fm[1],title:fm[2].trim()});
}
if(tasks.length===0) tasks.push({id:'FR1',title:'Implement '+epicTitle});

// Extract test case descriptions as subtasks (TC001, etc.) - up to 10
const subtasks=[];
const tcPat=/\*\*(TC\d+)[:\s]+([^*\n\r]+)\*\*/g;
let tm;
while((tm=tcPat.exec(md))!==null&&subtasks.length<10){
  subtasks.push({id:tm[1],title:tm[2].trim()});
}
if(subtasks.length===0) subtasks.push({id:'TC001',title:'Core feature verification for '+epicTitle});

console.log('\uD83C\uDFAF JIRA extraction: epic='+epicTitle+', tasks='+tasks.length+', subtasks='+subtasks.length);
return [{json:{...i,epicTitle,epicDescription,tasks,subtasks}}];
} catch (err) { console.error('❌ [Extract JIRA content]:', err.message); throw new Error('[Extract JIRA content] ' + err.message); }

try {
  const created = $input.first().json;
  const taskKey = created.key || '';
  const subtasks = created.subtasks || [];
  if (subtasks.length === 0) return [];
  return subtasks.map(s => ({ json: { ...created, currentSubtask: s, taskKey } }));
} catch (err) { console.error('❌ [Prepare Subtask Items]:', err.message); throw new Error('[Prepare Subtask Items] ' + err.message); }
